// The learned drum model: written by tools/showcontrol/drums/train.py, not by hand. The last
// `steps` steps' measurements in (Drums.featureCount each, newest first), standardised, one hidden
// layer, the chance of a kick, snare and hat out.

import Foundation

struct DrumModel {
    let mean: [Float], scale: [Float]
    let w1: [[Float]], b1: [Float]  // hidden × features
    let w2: [[Float]], b2: [Float]  // 3 × hidden
    let thresholds: [Float]         // kick, snare, hat
    let lead: Double                // how long after a hit starts it's found, on average
    let steps: Int

    func chances(_ f: [Float]) -> [Float] {
        var z = [Float](repeating: 0, count: f.count)
        for i in 0..<f.count { z[i] = (f[i] - mean[i]) * scale[i] }
        let h = w1.indices.map { j -> Float in
            var s = b1[j]
            for i in 0..<z.count { s += w1[j][i] * z[i] }
            return max(0, s)
        }
        return w2.indices.map { k in
            var s = b2[k]
            for j in 0..<h.count { s += w2[k][j] * h[j] }
            return 1 / (1 + expf(-s))
        }
    }

